import os as _os
LEAN = _os.path.dirname(_os.path.dirname(_os.path.abspath(__file__)))
WORK = _os.environ.get('GLUE_WORK', _os.path.join(LEAN, '.lake', 'glue-work'))
_os.makedirs(WORK, exist_ok=True)
# gen_gate.py: regenerates lean/BoltProof/Bridge/Glue/SimpleMulti/GateItems.lean
HEAD = "import BoltProof.Bridge.Glue.SimpleMulti.Weld\n\n/-!\n# The gate stack's items\n\nThe rebuild regions read the stack under the gate flag (`gateT`, suffix 1425) by depth. These lemmas name the\nitems the refinement needs: the spend's own fields and constants the first rebuild reuses (the new token's\nlock-length varint, the pay-to-proof template, the scriptCode's issuer push and suffix, the value, the\ngrandparent and balance fields, the fifth interop slot) and the two piece sets, item `62 + j` being `psA.p j`\nand item `137 + j` being `psB.p j`. All hold by `rfl` for each next type, except the merge flag (item 2, empty off a merge) and the\nvarint (item 0), which needs the spent lock's widths. Generated by the glue's `gen_gate.py`.\n-/\n\nset_option autoImplicit false\nset_option linter.unusedSimpArgs false\n\nnamespace BoltProof.Glue.SimpleMulti\n\nopen BsvScript BsvScript.Numbers\nopen BoltProof.Bridge.Generated\nopen BoltProof.Glue.MinSimple (sc scLen)\n\n"
TAIL = "theorem gateT_item2 (f : Fields) (a : Args) (S : List Bytes) (h : a.nty = [0x20] ∨ a.nty = [0x22]) :\n    item (gateT f a S) 2 = [] := by\n  unfold gateT; split_ifs with h1 h2\n  · rfl\n  · rfl\n  · rcases h with h | h <;> contradiction\n\n/-- The new token's lock-length varint on a settle: the lock is 4946 bytes. -/\ntheorem gateT_item0 {f : Fields} {a : Args} (S : List Bytes) (hwf : WF f) (hsc : sc a.pre = lockScript f)\n    (hop : 104 ≤ a.pre.length) (hnty : a.nty = [0x20] ∨ a.nty = [0x22] ∨ a.nty = [0x24])\n    (hlen : a.nty = [0x22] → (padN 16 (encode (decode f.bal - decode f.balCommit))).length = 16)\n    (hlen24 : a.nty = [0x24] → (padN 16 (encode (decode f.bal + decode f.balCommit))).length = 16) :\n    item (gateT f a S) 0 = [253, 0x52, 0x13] := by\n  have hsc' : List.take (decode (List.take 2 (List.drop 105 a.pre))).toNat (List.drop 107 a.pre) = lockScript f := hsc\n  have hm : min 36 (a.pre.length - 68) = 36 := by omega\n  rcases hnty with h | h | h\n  · simp only [gateT, h, ↓reduceIte, gateT_20, item, List.getElem?_cons_zero, Option.getD_some, hsc']\n    simp [lockScript, hwf.bal, hwf.balCommit, hwf.pkh, hwf.com, hwf.com2, hwf.ogp, hwf.ty, hwf.outIdx, hwf.parent,\n      hwf.gp, hwf.issuer, List.take_left', suffix_length, hm]\n    decide\n  · have h' : a.nty ≠ [0x20] := by rw [h]; decide\n    simp only [gateT, h, h', ↓reduceIte, gateT_22, item, List.getElem?_cons_zero, Option.getD_some, hsc']\n    simp [lockScript, hwf.bal, hwf.balCommit, hwf.pkh, hwf.com, hwf.com2, hwf.ogp, hwf.ty, hwf.outIdx, hwf.parent,\n      hwf.gp, hwf.issuer, suffix_length, hlen h, hm]\n    decide\n  · have h' : a.nty ≠ [0x20] := by rw [h]; decide\n    have h'' : a.nty ≠ [0x22] := by rw [h]; decide\n    simp only [gateT, h', h'', ↓reduceIte, gateT_24, item, List.getElem?_cons_zero, Option.getD_some, hsc']\n    simp [lockScript, hwf.bal, hwf.balCommit, hwf.pkh, hwf.com, hwf.com2, hwf.ogp, hwf.ty, hwf.outIdx, hwf.parent,\n      hwf.gp, hwf.issuer, suffix_length, hlen24 h, hm]\n    decide\n\ntheorem gateT_item2_24 (f : Fields) (a : Args) (S : List Bytes) (h : a.nty = [0x24]) :\n    item (gateT f a S) 2 = [1] := by\n  have h' : a.nty ≠ [0x20] := by rw [h]; decide\n  have h'' : a.nty ≠ [0x22] := by rw [h]; decide\n  simp only [gateT, h', h'', ↓reduceIte]; rfl\n\nend BoltProof.Glue.SimpleMulti\n"
items = [(12, '[29, 2, 176, 23, 136, 118, 169, 20]'), (14, 'scSuffix a.pre'),
         (15, 'List.take 34 (List.drop 212 (sc a.pre))'),
         (30, 'List.take 8 (List.drop (107 + (decode (List.take 2 (List.drop 105 a.pre))).toNat) a.pre)'),
         (36, 'f.gp'), (39, 'f.outIdx'), (41, 'f.ogp'), (46, 'f.bal'), (59, 'a.i3'), (60, 'a.i4'), (61, 'a.i5')] + [(62 + j, 'a.psA.p%d' % j) for j in range(75)] + [(137 + j, 'a.psB.p%d' % j) for j in range(75)]
out = HEAD
for n, rhs in items:
    out += 'theorem gateT_item%d (f : Fields) (a : Args) (S : List Bytes) : item (gateT f a S) %d = %s := by\n  unfold gateT; split_ifs <;> rfl\n\n' % (n, n, rhs)
out += TAIL
open(LEAN + '/BoltProof/Bridge/Glue/SimpleMulti/GateItems.lean', 'w').write(out)
